            Ok(bytes) if !bytes.is_empty() => continue,
            Ok(_) => {}
            Err(ref e) if keychain::is_not_found(e) => {}
            Err(e) => {
                tracing::warn!(error = %e, "share1 backfill: synced slot read failed; skipping");
